const bookingSlotRecordsFor = (tenantId) => { const timeZone = tenants[tenantId].timeZone; const now = new Date(); const today = zonedParts(now, timeZone); return bookingSlotDefinitions.map((definition) => { const date = new Date(Date.UTC(today.year, today.month - 1, today.day + definition.dayOffset)); const startsAt = zonedLocalToUtc({ year: date.getUTCFullYear(), month: date.getUTCMonth() + 1, day: date.getUTCDate(), hour: definition.hour, minute: definition.minute }, timeZone); const endsAt = new Date(startsAt.getTime() + 60 * 60 * 1000); return { id: `${definition.id}-${startsAt.toISOString().slice(0, 10)}`, label: definition.label, startsAt: startsAt.toISOString(), endsAt: endsAt.toISOString(), timeZone }; }); };
