const queueJobNotification = (saved, job, template, channel = 'SMS', dedupe = true) => { const templates = { confirmation: `${job.service} is confirmed for ${job.time}.`, rescheduled: `${job.service} has been rescheduled to ${job.time}.`, en_route: `${job.technician || 'Your technician'} is on the way for your ${job.service} appointment.`, completed: `${job.service} is complete. Thank you for choosing us.` }; if (!templates[template] || !['SMS', 'Email'].includes(channel)) return null; const existing = saved.messages.find((item) => dedupe && item.jobId === job.id && item.template === template && item.channel === channel); if (existing) return existing; const message = { id: `MSG-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, tenantId: job.tenantId, jobId: job.id, ...(job.customerId ? { customerId: job.customerId } : {}), customer: String(job.customer || job.customerId).slice(0, 100), channel, template, message: templates[template], status: 'Queued (provider pending)', queuedAt: new Date().toISOString() }; saved.messages.unshift(message); recordActivity(saved, message.customer, channel, `Job notification queued (${template}): ${message.message}`, message.status); return message; };
